package com.networkmonitor.dto;
import com.networkmonitor.entity.DeviceType;
public class DiscoveredDeviceDto{private String ipAddress,hostname,macAddress,vendor,osClue,suggestedName;private boolean reachable,alreadyMonitored;private Double latencyMs,packetLossPercent;private DeviceType suggestedType;public DiscoveredDeviceDto(){}public DiscoveredDeviceDto(String ip,String host,boolean r,String name,DeviceType type,boolean existing){ipAddress=ip;hostname=host;reachable=r;suggestedName=name;suggestedType=type;alreadyMonitored=existing;}public String getIpAddress(){return ipAddress;}public void setIpAddress(String v){ipAddress=v;}public String getHostname(){return hostname;}public void setHostname(String v){hostname=v;}public boolean isReachable(){return reachable;}public void setReachable(boolean v){reachable=v;}public Double getLatencyMs(){return latencyMs;}public void setLatencyMs(Double v){latencyMs=v;}public Double getPacketLossPercent(){return packetLossPercent;}public void setPacketLossPercent(Double v){packetLossPercent=v;}public String getMacAddress(){return macAddress;}public void setMacAddress(String v){macAddress=v;}public String getVendor(){return vendor;}public void setVendor(String v){vendor=v;}public String getOsClue(){return osClue;}public void setOsClue(String v){osClue=v;}public String getSuggestedName(){return suggestedName;}public void setSuggestedName(String v){suggestedName=v;}public DeviceType getSuggestedType(){return suggestedType;}public void setSuggestedType(DeviceType v){suggestedType=v;}public boolean isAlreadyMonitored(){return alreadyMonitored;}public void setAlreadyMonitored(boolean v){alreadyMonitored=v;}}
